+    /// t(a INT PK, b TEXT, c BOOL) and u(a INT PK, d TEXT) — `a` is deliberately
+    /// on both sides so ambiguity is testable.
+    fn cat() -> Catalog {
+        let mut c = Catalog::new();
+        c.create(Schema {
+            table: "t".into(),
+            columns: vec![
+                Column {
+                    name: "a".into(),
+                    ty: Type::Int,
+                    primary_key: true,
+                },
+                Column {
+                    name: "b".into(),
+                    ty: Type::Text,
+                    primary_key: false,
+                },
+                Column {
+                    name: "c".into(),
+                    ty: Type::Bool,
+                    primary_key: false,
+                },
+            ],
+        })
+        .unwrap();
+        c.create(Schema {
+            table: "u".into(),
+            columns: vec![
+                Column {
+                    name: "a".into(),
+                    ty: Type::Int,
+                    primary_key: true,
+                },
+                Column {
+                    name: "d".into(),
+                    ty: Type::Text,
+                    primary_key: false,
+                },
+            ],
+        })
+        .unwrap();
+        c
+    }
+
+    fn select(s: SelectStmt) -> Result<LogicalPlan> {
+        lower(&Statement::Select(s), &cat())
+    }
+
+    fn project_exprs(plan: &LogicalPlan) -> &[(Expr, String)] {
+        match plan {
+            LogicalPlan::Project { exprs, .. } => exprs,
+            other => panic!("expected Project, got {other:?}"),
+        }
+    }
