+            buf.extend_from_slice(name.as_bytes());
+            buf.extend_from_slice(&t.heap.first_page().to_le_bytes());
+            let index_root = t.index.as_ref().map_or(0, BTree::root);
+            buf.extend_from_slice(&index_root.to_le_bytes());
